ite-space:nowrap}.status.wait{color:var(--orange);border-color:rgba(244,179,79,.25);background:rgba(244,179,79,.07)}.status.closed{color:#96a7b7;border-color:#32465b;background:#122338}.quick a{display:flex;align-items:center;gap:10px;padding:11px 14px;border-bottom:1px solid var(--line);font-size:9px}.quick a:last-child{border:0}.quick a:hover{background:#102139}.qicon{width:28px;height:28px;border-radius:7px;background:#102842;color:#63cff8;display:grid;place-items:center;font-weight:800}.quick small{display:block;color:#6d8296;font-size:7px;margin-top:3px}.quick .arrow{margin-left:auto;color:#5dcaf5}.below{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px}.empty{padding:28px;text-align:center;color:#71869b;font-size:9px}.support-cta{margin:22px 0;background:linear-gradient(120deg,#0c1d32,#0a1829);border:1px solid var(--line);border-radius:10px;padding:23px;display:flex;align-items:center;justify-content:space-between;gap:18px}.support-cta h2{font-size:21px;margin:6px 0}.support-cta p{color:var(--muted);font-size:9px;margin:0}.support-buttons{display:flex;gap:8px}.field{width:100%;padding:9px;border:1px solid var(--line2);background:#071626;color:#fff;border-radius:7px;margin-bottom:8px;outline:none;font-size:9px}.field:focus{border-color:#55c7f2}.field option{background:#0b1a2d}.ticket-form{padding:13px}.footer{margin-top:28px;background:#071426;border-top:1px solid var(--line)}.footerin{max-width:1160px;margin:auto;padding:28px 22px;display:grid;grid-template-columns:1.2fr repeat(3,1fr);gap:30px}.footer h4{font-size:9px;color:#8ddcff;margin:0 0 10px}.footer a,.footer p{display:block;color:#788da2;font-size:8px;line-height:1.9;margin:0}.copyright{max-width:1160px;margin:auto;padding:13px 22px;border-top:1px solid #13263e;color:#516a81;font-size:7px}.mobile-nav{display:none}
