</style></head><body><header class="top"><div class="topin"><a class="brand" href="/client"><span class="logo">◢</span><span>NODEXA<small>HOSTING CLOUD</small></span></a><div class="topactions"><span>Hej, {{$user->username??'kunde'}}</span><a href="/account">Min konto</a><a href="/store">Bestilling</a><a href="/auth/logout">Log ud</a></div></div></header><main class="wrap"><section class="hero"><div class="hero-grid"><div><div class="eyebrow">Kundecenter / Overblik</div><h1>Dit kundeområde. Alt under kontrol.</h1><p>Få et hurtigt overblik over dine services, fakturaer og supportsager — og fortsæt direkte til det, du skal bruge.</p><div class="hero-buttons"><a class="btn" href="/store">▤ &nbsp; Bestil et produkt →</a><a class="btn secondary" href="#new-ticket">◉ &nbsp; Support</a></div></div><div class="account-card"><small>DIN KONTO</small><strong>{{$user->username??$user->email}}</strong><small>{{$user->email}}</small></div></div></section><div class="section-head"><div><div class="section-kicker">Kontostatus</div><h2>Dit overblik</h2></div><span>Genveje til dine vigtigste områder</span></div><section class="stats"><a class="stat" href="#services"><div class="stat-icon">▤</div><strong>{{$services->count()+$vpsServices->count()}}</strong><span>Produkter</span><small>Aktive tjenester</small></a><a class="stat" href="/client/invoices"><div class="stat-icon">▣</div><strong>{{$invoices->where('status','unpaid')->count()}}</strong><span>Ubetalte fakturaer</span><small>Kræver evt. handling</small></a><a class="stat" href="#tickets"><div class="stat-icon">◫</div><strong>{{$tickets->where('status','!=','closed')->count()}}</strong><span>Support sager</span><small>Åbne tickets</small></a><a class="stat" href="/client/invoices"><div class="stat-icon">▧</div><strong>{{$invoices->count()}}</strong><span>Fakturaer</span><small>Alle fakturaer</small></a></section><div class="section-head"><div><div class="section-kicker">Aktivitet</div><h2>Seneste fra din konto</h2></div><span>Services, sager og kontoaktivitet</span></div><section class="activity-grid"><div class="card" id="services"><div class="cardhead"><strong>▣ Dine aktive produkter/services</strong><a href="/store">+ Bestil nyt</a></div>@foreach($services->take(4) as $s)<a class="item" href="/"><div><div class="item-title">{{$s->name??('Game Server #'.$s->id)}}</div><div class="meta">Game Server · Service #{{$s->id}}</div></div><span class="status">Aktiv</span></a>@endforeach @foreach($vpsServices->take(4) as $v)<a class="item" href="/client/vps/{{$v->id}}"><div><div class="item-title">{{$v->hostname?:('VPS #'.$v->id)}}</div><div class="meta">VPS · {{$v->ip_address?:'IP afventer'}}</div></div><span class="status {{$v->status==='awaiting_payment'?'wait':''}}">{{str_replace('_',' ',$v->status)}}</span></a>@endforeach @if($services->isEmpty()&&$vpsServices->isEmpty())<div class="empty">Det ser ud som om du ikke har nogle produkter endnu. <a href="/store" style="color:#5bcdf7">Afgiv en ordre nu.</a></div>@endif</div><div class="card quick"><div class="cardhead"><strong>Genveje</strong></div><a href="/store"><span class="qicon">▤</span><span><b>Køb et produkt</b><small>Se alle produkter</small></span><span class="arrow">›</span></a><a href="#new-ticket"><span class="qicon">◫</span><span><b>Opret support sag</b><small>Få hjælp fra vores support</small></span><span class="arrow">›</span></a><a href="/client/invoices"><span class="qicon">▧</span><span><b>Se dine fakturaer</b><small>Betal og download</small></span><span class="arrow">›</span></a><a href="/account"><span class="qicon">◎</span><span><b>Min konto</b><small>Rediger dine oplysninger</small></span><span class="arrow">›</span></a></div></section><section class="below"><div class="card" id="tickets"><div class="cardhead"><strong>Seneste support sager</strong><a href="#new-ticket">+ Opret en ny sag</a></div>@forelse($tickets->take(5) as $t)<a class="item" href="/client/tickets/{{$t->id}}"><div><div class="item-title">#{{$t->id}} · {{$t->subject}}</div><div class="meta">{{ucfirst($t->department??'support')}} · {{$t->updated_at}}</div></div><span class="status {{$t->status==='closed'?'closed':'wait'}}">{{str_replace('_',' ',$t->status)}}</span></a>@empty<div class="empty">Ingen sager fundet. Har du brug for hjælp, skal du bare åbne en sag.</div>@endforelse</div><div class="card"><div class="cardhead"><strong>Seneste fakturaer</strong><a href="/client/invoices">Vis alle</a></div>@forelse($invoices->take(5) as $i)<a class="item" href="/client/invoices/{{$i->id}}"><div><div class="item-title">{{$i->number??('Faktura #'.$i->id)}}</div><div class="meta">{{number_format((float)($i->total??0),2,',','.')}} {{$i->currency??'DKK'}}</div></div><span class="status {{$i->status==='paid'?'':'wait'}}">{{$i->status}}</span></a>@empty<div class="empty">Ingen fakturaer endnu.</div>@endforelse</div></section><section class="card" id="new-ticket"><div class="cardhead"><strong>Opret support sag</strong><span style="font-size:8px;color:#71869b">Vi hjælper dig hurtigst muligt</span></div><form method="POST" action="/client/tickets" class="ticket-form">@csrf<input class="field" name="subject" required placeholder="Emne"><select class="field" name="department"><option value="support">Support</option><option value="billing">Fakturering</option><option value="sales">Salg</option></select><select class="field" name="priority"><option value="low">Lav prioritet</option><option value="normal" selected>Normal prioritet</option><option value="high">Høj prioritet</option></select><textarea class="field" name="message" required rows="4" placeholder="Beskriv hvad vi kan hjælpe med..."></textarea><button class="btn">Opret sag →</button></form></section><section class="support-cta"><div><div class="section-kicker">Direkte linje</div><h2>Kontakt uden <i>ventetid.</i></h2><p>Vælg den kanal, der passer til din opgave. Du lander direkte hos vores support.</p></div><div class="support-buttons"><a class="btn" href="#new-ticket">Opret sag →</a><a class="btn secondary" href="/account">Kontakt os</a></div></section></main><footer class="footer"><div class="footerin"><div><div class="brand"><span class="logo">◢</span><span>NODEXA</span></div><p style="margin-top:10px">Professionel hosting, bygget til performance.</p></div><div><h4>Vores produkter</h4><a href="/store/vps">VPS Hosting</a><a href="/store/games">Gaming VPS Hosting</a><a href="/store">Webhosting</a><a href="/store">Se alle produkter</a></div><div><h4>Support</h4><a href="#new-ticket">Opret sag</a><a href="#tickets">Mine sager</a><a href="/client/invoices">Fakturaer</a><a href="/account">Min konto</a></div><div><h4>Information</h4><a href="/">Forside</a><a href="/store">Produkter</a><a href="/account">Konto</a><a href="/auth/logout">Log ud</a></div></div><div class="copyright">Copyright © 2026 Nodexa. Alle rettigheder forbeholdes.</div></footer></body></html>